class Solution:
    def validSubarraySize(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        st = []
        for i in range(n + 1):
            while st and (i == n or nums[st[-1]] >= nums[i]):
                j = st.pop()
                k = i - (st[-1] if st else -1) - 1
                if nums[j] * k > threshold:
                    return k
            if i < n:
                st.append(i)
        return -1

