class Solution {
public:
    int validSubarraySize(vector<int>& nums, int threshold) {
        int n = nums.size();
        vector<int> st;
        for (int i = 0; i <= n; i++) {
            while (!st.empty() && (i == n || nums[st.back()] >= nums[i])) {
                int j = st.back(); st.pop_back();
                long long k = i - (st.empty() ? -1 : st.back()) - 1;
                if ((long long) nums[j] * k > threshold) return (int) k;
            }
            if (i < n) st.push_back(i);
        }
        return -1;
    }
};

