class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i <= n; i++) {
            while (!st.isEmpty() && (i == n || nums[st.peek()] >= nums[i])) {
                int j = st.pop();
                long k = (long) i - (st.isEmpty() ? -1 : st.peek()) - 1;
                if ((long) nums[j] * k > threshold) return (int) k;
            }
            if (i < n) st.push(i);
        }
        return -1;
    }
}

