class Solution:
    def validSubarraySize(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        par = list(range(n))
        sz = [0] * n
        act = [False] * n
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        for i in sorted(range(n), key=lambda i: -nums[i]):
            act[i] = True
            sz[i] = 1
            for j in (i - 1, i + 1):
                if 0 <= j < n and act[j]:
                    a, b = find(i), find(j)
                    if a != b:
                        par[a] = b
                        sz[b] += sz[a]
            r = find(i)
            if nums[i] * sz[r] > threshold:
                return sz[r]
        return -1

