class Solution {
    vector<int> par, sz;
    int find(int x) { while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; } return x; }
public:
    int validSubarraySize(vector<int>& nums, int threshold) {
        int n = nums.size();
        par.resize(n); sz.assign(n, 0);
        vector<char> act(n, 0);
        iota(par.begin(), par.end(), 0);
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b){ return nums[a] > nums[b]; });
        for (int i : ord) {
            act[i] = 1; sz[i] = 1;
            for (int j : {i - 1, i + 1})
                if (j >= 0 && j < n && act[j]) {
                    int a = find(i), b = find(j);
                    if (a != b) { par[a] = b; sz[b] += sz[a]; }
                }
            int r = find(i);
            if ((long long) nums[i] * sz[r] > threshold) return sz[r];
        }
        return -1;
    }
};

